import numpy as np

def prox_l1(v, t):
    return np.sign(v) * np.maximum(np.abs(v) - t, 0.0)

def prox_nonneg(v, t=None):
    return np.maximum(v, 0.0)

def prox_l2ball(v, t=None, r=1.0):
    n = np.linalg.norm(v)
    return v if n <= r else (r/n)*v

import numpy as np

def subgradient_l1_reg(A, b, lam, iters=2000, a=0.5):
    x = np.zeros(A.shape[1]); best = x.copy()
    fbest = np.inf
    for k in range(1, iters+1):
        g = A.T @ (A @ x - b) + lam*np.sign(x)  # subgradient (0 at x_i=0)
        x = x - (a/np.sqrt(k))*g
        f = 0.5*np.sum((A@x-b)**2) + lam*np.sum(np.abs(x))
        if f < fbest: fbest, best = f, x.copy()
    return best

def branch_and_bound(relax, is_integral, branch, sense='min'):
    best = None; best_val = float('inf')
    stack = [relax()]                 # root relaxation
    while stack:
        node = stack.pop()
        if node is None or node.bound >= best_val:
            continue                  # infeasible or pruned
        if is_integral(node):
            if node.value < best_val:
                best_val, best = node.value, node.solution
        else:
            stack.extend(branch(node)) # split into children
    return best, best_val

import numpy as np

def epsilon_greedy(pull, K, T, eps=0.1):
    counts = np.zeros(K); values = np.zeros(K)
    for t in range(T):
        if np.random.rand() < eps:
            a = np.random.randint(K)      # explore
        else:
            a = int(np.argmax(values))    # exploit
        r = pull(a)
        counts[a] += 1
        values[a] += (r - values[a]) / counts[a]  # running mean
    return values

from scipy.optimize import minimize

def rosen(x):
    return sum(100*(x[1:]-x[:-1]**2)**2 + (1-x[:-1])**2)

res = minimize(rosen, x0=[-1.2, 1.0], method='Nelder-Mead')
print(res.x, res.fun)
